    id:'configuration-change',title:'Configuration & change',summary:'Keep the physical or software change, its interfaces and its evidence aligned.',question:'What changed, which version is installed, and what evidence belongs to it?',category:'Engineering process',diagramType:'lifecycle',sources:['PR01','PR02','PR07','Q01','Q02'],links:['change-item','change-baseline','change-interface','change-test','dependency-configuration'],
